"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[9790],{79790:e=>{e.exports=JSON.parse('{"slug":"vvp-kitaya-3-kvartal-2026-eksport","locale":"es","title":"China acelera al 4,5% gracias a las exportaciones, mientras el comercio minorista solo crece un 1,1%","description":"El PIB chino del tercer trimestre de 2026 sube un 4,5%. Exportaciones +36% y ventas minoristas +1,1%. Por qu\xe9 es fr\xe1gil depender del exterior y qu\xe9 implica para Rusia.","blocks":[{"id":"b001","kind":"paragraph","text":"El PIB chino de julio a septiembre creci\xf3 un 4,5% frente a 2025, seg\xfan datos del 19 de octubre, por encima del 4,4% previsto. El segundo trimestre hab\xeda crecido un 4,3%, m\xednimo desde 2022. El avance trimestral fue del 1,2%. En 9 meses suma un 4,6%, con un PIB de 107,1 billones de yuanes. La meta anual del 4,5–5% parece alcanzable."},{"id":"b002","kind":"paragraph","text":"El principal motor fue la exportaci\xf3n: en septiembre creci\xf3 un 36,3% interanual y la importaci\xf3n un 31%. El super\xe1vit mensual fue de $133,5 mil millones, el mayor en 20 meses. La exportaci\xf3n de chips duplic\xf3 su valor en 9 meses y la de ordenadores y autom\xf3viles aument\xf3 cerca del 54%. La producci\xf3n industrial de septiembre creci\xf3 un 5,5%."},{"id":"b003","kind":"paragraph","text":"Dentro del pa\xeds es distinto. Las ventas minoristas aumentaron un 1,1%, mejor que el 0,5% previsto, pero poco. La inversi\xf3n fija de 9 meses cay\xf3 un 7,2%; la privada, un 10,4%; y la inmobiliaria, un 20,6%. La superficie vendida de vivienda nueva baj\xf3 un 13,2%. Como las familias concentran ahorros en pisos, el abaratamiento las hace sentirse m\xe1s pobres y gastar con cautela."},{"id":"b004","kind":"paragraph","text":"Imagina un caf\xe9 familiar que exporta pasteles a la ciudad vecina. Factura m\xe1s y ocupa a sus cocineros, pero los vecinos propios acuden menos. Mientras el cliente externo compra, va bien; si encuentra otra panader\xeda, se acaba el crecimiento porque no gan\xf3 p\xfablico local. Es crecer mediante demanda exterior: r\xe1pido, pero dependiente de decisiones ajenas. La UE ya intenta reducir las compras de productos chinos de alto valor."},{"id":"b005","kind":"paragraph","text":"Para Rusia importa la facturaci\xf3n exportadora. China es su mayor comprador de combustible: en septiembre adquiri\xf3 unos 9,1 mil millones de euros en petr\xf3leo, gas y carb\xf3n. Las f\xe1bricas ocupadas consumen energ\xeda; mientras haya pedidos externos se mantiene la demanda. Los buenos datos tambi\xe9n reducen la probabilidad de est\xedmulos internos: al cumplir el objetivo, Pek\xedn tiene menos incentivos para gastar."},{"id":"b006","kind":"paragraph","text":"Xu Tianchen, de Economist Intelligence Unit, espera que exportaciones e inversi\xf3n p\xfablica sostengan el cuarto trimestre. El riesgo es depender de una sola base. Menor inversi\xf3n mundial en IA o barreras europeas afectar\xedan a chips y coches; el consumidor propio a\xfan no sustituye al extranjero. Mantener pedidos ocupa f\xe1bricas y sostiene las compras de crudo ruso. Si caen, se ver\xe1 con qu\xe9 rapidez Pek\xedn puede estimular el consumo interno."},{"id":"b007","kind":"heading","text":"\xbfCu\xe1nto creci\xf3 el PIB chino en el tercer trimestre de 2026?"},{"id":"b008","kind":"paragraph","text":"Un 4,5% frente a julio-septiembre de 2025, por encima del 4,4% esperado. El segundo trimestre fue del 4,3%, m\xednimo desde 2022. En 9 meses crece un 4,6%, con una meta del 4,5–5%."},{"id":"b009","kind":"heading","text":"\xbfPor qu\xe9 se considera desequilibrado el crecimiento?"},{"id":"b010","kind":"paragraph","text":"Las exportaciones subieron un 36,3% en septiembre y las ventas minoristas solo un 1,1%. La inversi\xf3n inmobiliaria de 9 meses cay\xf3 un 20,6%. Crece por compradores extranjeros, no por los propios hogares."},{"id":"b011","kind":"heading","text":"\xbfQu\xe9 significa para Rusia la aceleraci\xf3n china?"},{"id":"b012","kind":"paragraph","text":"China es el mayor comprador de petr\xf3leo, gas y carb\xf3n rusos. Mientras sus f\xe1bricas reciban pedidos de exportaci\xf3n, se sostiene el combustible. Si cae la demanda exterior, su mercado interno a\xfan no est\xe1 listo para sustituirla."}],"sources":[{"label":"El PIB chino crece un 4,5% en el tercer trimestre","url":"https://www.interfax.ru/business/1123374"},{"label":"China acelera gracias al auge exportador","url":"https://www.cnbc.com/2026/10/19/chinas-economic-growth-quickens-to-4point6percent-as-exports-surge-stimulus-rolls-out.html"},{"label":"China recupera el 4.5% y acerca la meta anual","url":"https://www.bloomberg.com/news/articles/2026-10-19/china-s-growth-rebounds-to-4-5-puts-annual-target-within-reach"},{"label":"El PIB chino supera previsiones con un 4.5%; mejoran las ventas minoristas","url":"https://investinglive.com/news/china-q3-gdp-beats-forecasts-at-4-5-retail-sales-grow-at-fastest-pace-since-march/"},{"label":"La econom\xeda china resiste en los primeros tres trimestres de 2026","url":"https://www.indexbox.io/blog/chinas-economy-holds-steady-in-first-three-quarters-of-2026-as-trade-and-industry-outpace-broader-growth/"},{"label":"Las exportaciones chinas suben un 36.3% en septiembre y aumentan las presiones comerciales","url":"https://clickondetroit.com/business/2026/10/14/chinas-exports-surge-363-in-september-as-pressure-ramps-up-to-rebalance-trade"},{"label":"China registra el mayor super\xe1vit en 20 meses","url":"https://tradingeconomics.com/china/balance-of-trade/news/591695"},{"label":"Septiembre de 2026: exportaciones rusas de combustibles y sanciones","url":"https://energyandcleanair.org/september-2026-monthly-analysis-of-russian-fossil-fuel-exports-and-sanctions/"}],"sourceBodySha256":"a43116f5bc45095d81495bfb1beae8eb81d22f98eafffb5342e2297d883572c6"}')}}]);